from fractions import Fraction as F
import json
rows=[('A',5,(0,0,0,1)),('A',6,(1,0,1,0)),('B',11,(0,0,0,1)),('B',5,(0,1,1,0)),('C',6,(0,1,0,1)),('C',4,(1,0,1,1)),('D',6,(0,0,1,0)),('D',8,(1,1,0,0))]
ids='TUVW'
cost=[F(1),F(1),F(17,10),F(21,10)]
loss=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
def stop(s):
 w=sum(rows[i][1] for i in s)
 return min((sum(F(rows[i][1],w)*loss[a]['ABCD'.index(rows[i][0])] for i in s),'ABCD'[a]) for a in range(4))
def best(s,available,n):
 opts=[stop(s)]
 if n:
  for t in available:
   opts.append((test(s,available,n,t),ids[t]))
 return min(opts)
def test(s,available,n,t):
 w=sum(rows[i][1] for i in s)
 val=cost[t]
 for b in (0,1):
  branch=[i for i in s if rows[i][2][t]==b]
  if branch:
   val+=F(sum(rows[i][1] for i in branch),w)*best(branch,[x for x in available if x!=t],n-1)[0]
 return val
s=list(range(8)); av=list(range(4))
first_losses={'STOP':float(stop(s)[0])}
first_losses.update({ids[t]:float(test(s,av,2,t)) for t in av})
value,first=best(s,av,2)
nexts={}
if first in ids:
 t=ids.index(first)
 for b in (0,1):
  branch=[i for i in s if rows[i][2][t]==b]
  nexts[str(b)]=best(branch,[x for x in av if x!=t],1)[1] if branch else 'IMPOSSIBLE'
print(json.dumps({'first':first,'first_losses':first_losses,'next':nexts}))
print('exact best',value)

