from fractions import Fraction as F
import json
# U=0, repeated stored display conveys no additional observation
rows=[('A',5,(0,0,1)),('A',6,(1,1,0)),('B',11,(0,0,1)),('C',4,(1,1,1)),('D',6,(0,1,0))]
L={'A':[0,7,10,21],'B':[7,0,22,11],'C':[19,13,0,19],'D':[12,6,13,0]}
def losses(rs):
 w=sum(r[1] for r in rs)
 return {a:sum(F(r[1],w)*ls['ABCD'.index(r[0])] for r in rs) for a,ls in L.items()}
w=sum(r[1] for r in rows)
p={a:float(F(sum(r[1] for r in rows if r[0]==a),w)) for a in 'ABCD'}
v=losses(rows)
pol={}
for j,(t,c) in enumerate(zip('TVW',[F(7),F(17,10),F(21,10)])):
 val=c; pol[t]={}
 for b in (0,1):
  rs=[r for r in rows if r[2][j]==b]
  if rs:
   ls=losses(rs); a=min(ls,key=ls.get)
   val+=F(sum(r[1] for r in rs),w)*ls[a]; pol[t][str(b)]=a
  else: pol[t][str(b)]='IMPOSSIBLE'
 v[t]=val
a=min(v,key=v.get)
print(json.dumps({'posterior':p,'remaining_losses':{k:float(x) for k,x in v.items()},'action':a,'repair_after':pol.get(a,{})}))

